tool.command:
set -euo pipefail;

curl -L "${vcf_url}" -o downloaded_input;

if bgzip -t downloaded_input 2>/dev/null; then
    mv downloaded_input input.vcf.gz;
else
    echo "Re-compressing to BGZF...";
    gunzip -c downloaded_input | bgzip -c > input.vcf.gz;
fi;

bcftools index --tbi input.vcf.gz;

bcftools view
#if $samples_file
    --samples-file '${samples_file}'
#end if
#if $regions.regions_select == "type_regions"
    --regions '${regions.region_string}'
#elif $regions.regions_select == "upload_file"
    --regions-file '${regions.regions_file}'
#end if
    --output-type z
    --output '${output_vcf}'
    input.vcf.gz > /dev/null;
